from lxml import etree
from zipfile import ZipFile
for f in ['documents/turn-2-redline-meridian.docx','documents/gmra-2011-icma-standard-form.docx']:
 with ZipFile(f) as z: root=etree.fromstring(z.read('word/document.xml'))
 ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
 print('\n',f)
 for tag in ['ins','del','commentRangeStart','commentRangeEnd','commentReference']:
  els=root.xpath('.//w:'+tag,namespaces=ns)
  print(tag,len(els))
  for e in els[:5]:
   txt=''.join(e.xpath('.//w:t/text()|.//w:delText/text()',namespaces=ns))
   print(' ', e.get('{%s}author'%ns['w']), e.get('{%s}id'%ns['w']), repr(txt[:200]))
PY","description":"Inspect existing tracked changes","timeoutMs":120000}

