from lxml import etree
from zipfile import ZipFile
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with ZipFile('documents/turn-2-redline-meridian.docx') as z: root=etree.fromstring(z.read('word/document.xml'))
for pidx,p in enumerate(root.xpath('.//w:body/w:p',namespaces=ns),1):
    revs=p.xpath('.//w:ins|.//w:del',namespaces=ns)
    if revs:
      def txt(node): return ''.join(node.xpath('.//w:t/text()|.//w:delText/text()',namespaces=ns))
      full=''.join(p.xpath('.//w:t/text()|.//w:delText/text()',namespaces=ns))
      print('P',pidx, 'FULL',repr(full[:250]))
      for r in revs:
       print(' ',r.tag.rsplit('}',1)[1], 'id',r.get('{%s}id'%ns['w']),'author',r.get('{%s}author'%ns['w']),repr(txt(r)))
PY > revision-map.txt","description":"Map Turn 2 tracked revisions","timeoutMs":120000}

