# keep only first comment marker set and remove later; renumber all kept references to 0
seen=False
for p in root.xpath('.//w:p',namespaces=w):
 for e in list(p):
  if e.tag in ['{%s}commentRangeStart'%ns,'{%s}commentRangeEnd'%ns] or e.xpath('.//w:commentReference',namespaces=w):
