   elif seen and e.tag!='{%s}commentRangeEnd'%ns and not e.xpath('.//w:commentReference',namespaces=w): p.remove(e)
# easier remove all comments refs then keep no markers by using sample? 
for tag in ['commentRangeStart','commentRangeEnd','commentReference']:
 for e in root.xpath('.//w:'+tag,namespaces=w): e.getparent().remove(e)
files['word/document.xml']=etree.tostring(root,xml_declaration=True,encoding='UTF-8',standalone='yes')
